import * as store from './store.js';
import * as data from './data.js';
import * as audio from './audio.js';
import {esc,icon,toast,modal} from './ui.js';
import {t} from './i18n.js';
import {dashboard,learning,practice,stats} from './views/dashboard.js';
import {phrasebook,decks,reader,dialogues} from './views/library.js';
import {flashcards,quizBuilder,startQuiz,match} from './views/study.js';
import {alphabet,grammar,settings} from './views/reference.js';
const ctx={store,data,audio,esc,icon,toast,modal,items:[],language:null,register(items){for(const i of items)registry.set(i.id,i);},go(path){location.hash=`#/${store.state().language}/${path}`;},rerender:()=>render()};
const registry=new Map();let renderVersion=0;let cleanup;
const nav=['home','learn','practice','phrasebook','alphabet','grammar','stats'];
function applyTheme(){const s=store.state().settings;document.documentElement.dataset.theme=s.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):s.theme;document.documentElement.dataset.language=store.state().language;document.documentElement.style.fontSize=s.fontSize+'px';}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
function shell(route){const lang=ctx.language,s=store.state();return `<aside class="sidebar"><a class="brand" href="#/${lang.code}/home"><svg viewBox="0 0 32 38" fill="none" aria-hidden="true"><path d="M15 32V11M15 23Q0 21 3 9q13 0 12 14M15 16Q14 1 29 3q1 14-14 13" fill="none" stroke="currentColor" stroke-width="2.5"/></svg>parola<span class="sr-only"> home</span></a><nav class="nav" aria-label="Main">${nav.map(n=>`<a class="${['alphabet','grammar'].includes(n)?'desktop-only ':''}${(route===n||route==='lessons'&&n==='learn')?'active':''}" ${route===n?'aria-current="page"':''} href="#/${lang.code}/${n}">${icon(n)}<span>${t(n)}</span></a>`).join('')}</nav><div class="side-bottom"><div class="tip">🌿<strong>A little, every day.</strong>Big journeys begin with small conversations.</div><a class="profile" href="#/${lang.code}/settings"><span class="avatar">Y</span><span>You, the explorer<small>Level ${Math.floor(s.xp/250)+1} · Keep growing</small></span>${icon('settings')}</a></div></aside><div class="shell"><header class="topbar"><span class="breadcrumb muted">Your language garden</span><div class="status"><span class="online">Ready for a little practice</span><span aria-label="Study streak">🔥 ${store.streak()}</span><span class="xp-top">✦ ${s.xp} XP</span><label class="sr-only" for="language">Study language</label><select id="language" aria-label="Study language">${ctx.languages.map(l=>`<option value="${l.code}" ${lang.code===l.code?'selected':''}>${l.flag} ${l.name}</option>`).join('')}</select><a class="small-button pill" href="#/${lang.code}/settings" aria-label="Settings">${icon('settings')}</a></div></header><main class="content" id="main" tabindex="-1"><div id="storage-warning"></div><div id="voice-banner"></div><div id="view"><p class="loading">Gathering your words…</p></div></main></div>`;}
async function render(){const version=++renderVersion;cleanup?.();ctx.sessionCleanup?.();ctx.sessionCleanup=undefined;audio.stop();audio.endRecording();const parts=location.hash.replace(/^#\/?/,'').split('/');try{ctx.languages=await data.languages();const code=ctx.languages.some(l=>l.code===parts[0])?parts[0]:store.state().language;store.setLanguage(code);ctx.language=ctx.languages.find(l=>l.code===code)??ctx.languages[0];ctx.route=parts[1]||'home';ctx.params=new URLSearchParams(parts.slice(2).join('/'));applyTheme();document.querySelector('#app').innerHTML=shell(ctx.route);document.title=`${t(ctx.route)} · ${ctx.language.name} · Parola`;document.querySelector('#language').addEventListener('change',e=>{store.setLanguage(e.target.value);location.hash=`#/${e.target.value}/home`;});document.querySelector('#storage-warning').innerHTML=store.storageWarning()?`<p class="banner">${esc(store.storageWarning())}</p>`:'';
 const routes={home:dashboard,learn:learning,lessons:learning,practice,phrasebook,flashcards,quiz:quizBuilder,spelling:c=>startQuiz(c,{mode:'spelling'}),listening:c=>startQuiz(c,{mode:'listening'}),challenge:c=>startQuiz(c,{daily:true}),placement:c=>startQuiz(c,{placement:true}),match,alphabet,grammar,stats,settings,decks,reader,dialogues};const result=await (routes[ctx.route]||dashboard)(ctx);if(version!==renderVersion)return;if(typeof result==='function')cleanup=result;else cleanup=undefined;document.dispatchEvent(new Event('parola:render'));}catch(e){document.querySelector('#view').innerHTML=`<div class="empty"><h2>Let’s try that again.</h2><p>${esc(e.message)}</p><button class="button" id="retry">Reload study library</button></div>`;document.querySelector('#retry').onclick=()=>render();}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main')?.focus();return;}const button=e.target.closest('[data-audio]');if(!button)return;e.stopPropagation();const id=button.dataset.audio,item=registry.get(id);if(item)await audio.speak(item,ctx.language,!!button.dataset.slow,toast);});
document.addEventListener('parola:noaudio',e=>{const el=document.querySelector('#voice-banner');if(el)el.innerHTML=`<div class="banner"><strong>Let’s give ${esc(e.detail)} a voice.</strong> Install an offline voice: Windows → Settings → Time & language → Speech; Android → Text-to-speech → voice data; Apple → Accessibility → Spoken Content → Voices. Until then, use the written pronunciation guide. Browser voices may need a connection unless installed locally.</div>`;});
window.addEventListener('hashchange',render);render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).catch(()=>toast('Offline installation is unavailable here. Open on HTTPS or localhost.'));
